#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "Airtel_murs_9118";
const char* password = "air@10295";

WebServer server(80);

const int LED_PIN = 38;

void handleRoot() {
  server.send(
    200,
    "text/html",
    "<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"
    "<title>SADIK.AI</title></head>"
    "<body style='text-align:center;font-family:Arial'>"
    "<h1>SADIK.AI</h1>"
    "<h2>ESP32-S3 Control</h2>"
    "<p><a href='/on'><button style='font-size:25px;padding:15px'>LED ON</button></a></p>"
    "<p><a href='/off'><button style='font-size:25px;padding:15px'>LED OFF</button></a></p>"
    "</body></html>"
  );
}

void handleOn() {
  digitalWrite(LED_PIN, HIGH);
  server.sendHeader("Location", "/");
  server.send(303);
}

void handleOff() {
  digitalWrite(LED_PIN, LOW);
  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  Serial.begin(115200);

  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }

  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);

  server.begin();
}

void loop() {
  server.handleClient();
}
